import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"扩展模型与能力地图","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/extensions.md","filePath":"plugins/extensions.md","lastUpdated":1791890216000}'),o={name:"plugins/extensions.md"};function c(i,t,s,n,l,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="扩展模型与能力地图" tabindex="-1">扩展模型与能力地图 <a class="header-anchor" href="#扩展模型与能力地图" aria-label="Permalink to &quot;扩展模型与能力地图&quot;">​</a></h1><p>配置用于调参数，声明用于扩充目录，服务替换用于更换实现。三者组合使用，避免为了换一个字号重新写播放器。</p><table tabindex="0"><thead><tr><th>想做什么</th><th>建议边界</th></tr></thead><tbody><tr><td>字号、留白、颜色、交互</td><td>默认配置或 schema</td></tr><tr><td>第三种卡片样式</td><td><code>LYRA_INTERFACE_STYLES</code> 声明</td></tr><tr><td>新的播放模式</td><td>rules 提供者 + modes 声明</td></tr><tr><td>完整自定义界面</td><td>根 <code>frame</code> 替换</td></tr><tr><td>单独更换歌词或控件</td><td>对应 <code>lyrics</code>、<code>controls</code> 服务</td></tr><tr><td>音频解码与输出</td><td><code>playback</code> 服务 + provider 接口</td></tr><tr><td>媒体源与曲库</td><td><code>source</code> + catalog 接口</td></tr><tr><td>流派/语言规则</td><td><code>profile-classification</code> + classification 接口</td></tr><tr><td>插件仓库/搜索/市场 UI</td><td><code>plugin-catalog</code>、<code>plugin-search</code>、<code>plugin-market</code></td></tr></tbody></table><p>完整实际名字和配置表见<a href="/LyraPlayer-docs-site/reference/services">服务目录</a>。能力名是替换槽；包 id 是稳定身份。不要依赖多个同能力包的目录遍历顺序实现组合。当前加载器同一 capability 只选一个活动实现，其他有效包可以存在但未启用。</p><h2 id="公共接口与私有实现" tabindex="-1">公共接口与私有实现 <a class="header-anchor" href="#公共接口与私有实现" aria-label="Permalink to &quot;公共接口与私有实现&quot;">​</a></h2><p>通过 <code>host-&gt;query_interface</code> 获取可用能力；插件自己的 query_interface 发布提供者或声明。媒体统一使用 media request/sink/context，播放统一使用 typed playback command。当前 SDK 不含旧 transport/record 入口。</p><p>不把 <code>host-&gt;user</code> 强转 App；不引用隐藏 C++ 符号；不拿默认布局对象或 renderer GPU 句柄。更底层绘制需要公开 Scene 协议或插件自己的平台能力，不能假定无限制互操作。</p><h2 id="android-依赖" tabindex="-1">Android 依赖 <a class="header-anchor" href="#android-依赖" aria-label="Permalink to &quot;Android 依赖&quot;">​</a></h2><p>当前外部包为 Android arm64-v8a、API 26+。JavaVM 和 Activity 是平台扩展入口；运行时请求权限依赖宿主清单已经声明。多平台插件需要不同架构的库，并优雅处理空 VM/缺失接口。</p><p>下一步：<a href="/LyraPlayer-docs-site/plugins/first-plugin">编译第一个插件</a>。</p><p>媒体搜索、在线集合和资源提供见<a href="/LyraPlayer-docs-site/plugins/media">媒体数据插件</a>，使用可选接口复用默认 UI。</p>',11)])])}const _=e(o,[["render",c]]);export{u as __pageData,_ as default};
